import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import {
  DeleteObjectCommand,
  GetObjectCommand,
  PutObjectCommand,
  S3Client,
} from '@aws-sdk/client-s3';

/**
 * Banner keys are generated by the api: a UUID, then `.webp` for the banner or `-og.jpg` for its
 * link-preview image. Nothing else is ever stored.
 */
export const BANNER_KEY =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(\.webp|-og\.jpg)$/;

/** The link-preview image stored next to a banner. */
export function ogKeyFor(bannerKey: string): string {
  return bannerKey.replace(/\.webp$/, '-og.jpg');
}

/**
 * Where event banners live: local disk in development and tests, the uploads bucket in AWS. Either
 * way browsers fetch them through the api's banner route, which Cloudflare caches. Callers never
 * build image URLs themselves.
 */
export abstract class BannerStorage {
  abstract put(key: string, image: Buffer): Promise<void>;
  abstract remove(key: string): Promise<void>;
  abstract publicUrl(key: string): string;
  /** The stored bytes, or null if there is no such banner. */
  abstract read(key: string): Promise<Buffer | null>;
}

function checkKey(key: string): void {
  if (!BANNER_KEY.test(key)) throw new Error('Invalid banner key');
}

function contentType(key: string): string {
  return key.endsWith('-og.jpg') ? 'image/jpeg' : 'image/webp';
}

export class LocalDiskBannerStorage extends BannerStorage {
  private readonly dir: string;

  constructor(
    dir: string,
    private readonly baseUrl: string,
  ) {
    super();
    this.dir = resolve(dir);
  }

  async put(key: string, image: Buffer): Promise<void> {
    await mkdir(this.dir, { recursive: true });
    await writeFile(this.path(key), image);
  }

  async remove(key: string): Promise<void> {
    await rm(this.path(key), { force: true });
  }

  publicUrl(key: string): string {
    return `${this.baseUrl}/${key}`;
  }

  async read(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.path(key));
    } catch {
      return null;
    }
  }

  private path(key: string): string {
    checkKey(key);
    return join(this.dir, key);
  }
}

/**
 * The uploads bucket, under `banners/` (infra/README.md). The bucket encrypts with the
 * environment's KMS key. The task role can't list the bucket, so a missing key comes back as
 * AccessDenied rather than NoSuchKey; both read as "no such banner".
 */
export class S3BannerStorage extends BannerStorage {
  constructor(
    private readonly bucket: string,
    private readonly baseUrl: string,
    private readonly s3: Pick<S3Client, 'send'> = new S3Client({}),
  ) {
    super();
  }

  async put(key: string, image: Buffer): Promise<void> {
    await this.s3.send(
      new PutObjectCommand({
        Bucket: this.bucket,
        Key: this.objectKey(key),
        Body: image,
        ContentType: contentType(key),
      }),
    );
  }

  async remove(key: string): Promise<void> {
    await this.s3.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: this.objectKey(key) }));
  }

  publicUrl(key: string): string {
    return `${this.baseUrl}/${key}`;
  }

  async read(key: string): Promise<Buffer | null> {
    try {
      const object = await this.s3.send(
        new GetObjectCommand({ Bucket: this.bucket, Key: this.objectKey(key) }),
      );
      if (!object.Body) return null;
      return Buffer.from(await object.Body.transformToByteArray());
    } catch (error) {
      const name = (error as { name?: string }).name;
      if (name === 'NoSuchKey' || name === 'AccessDenied') return null;
      throw error;
    }
  }

  private objectKey(key: string): string {
    checkKey(key);
    return `banners/${key}`;
  }
}

export function bannerStorageFromEnv(env: NodeJS.ProcessEnv = process.env): BannerStorage {
  const transport = env.BANNER_STORAGE ?? 'local';
  const webUrl = env.WEB_URL ?? 'http://localhost:3000';
  const baseUrl = env.BANNER_PUBLIC_BASE_URL ?? `${webUrl}/api/public/banners`;
  if (transport === 's3') {
    if (!env.UPLOADS_BUCKET) throw new Error('BANNER_STORAGE=s3 needs UPLOADS_BUCKET');
    return new S3BannerStorage(env.UPLOADS_BUCKET, baseUrl);
  }
  if (transport !== 'local') {
    throw new Error(`BANNER_STORAGE=${transport} is not supported`);
  }
  return new LocalDiskBannerStorage(env.BANNER_DIR ?? 'var/banners', baseUrl);
}
